-- Structured Workspace Actions: action-time location snapshots and safe field diffs.
-- Existing action-log rows remain untouched (structured_version = 0). New rows are
-- generated by trusted database triggers from accepted workspace-document changes.
-- This migration never updates or deletes business records.

begin;

alter table public.beekeep_workspace_action_log
    add column if not exists structured_version smallint not null default 0,
    add column if not exists apiary_id bigint,
    add column if not exists apiary_name_snapshot text,
    add column if not exists hive_id bigint,
    add column if not exists hive_name_snapshot text,
    add column if not exists changes jsonb not null default '[]'::jsonb,
    add column if not exists affected_hive_count integer,
    add column if not exists affected_hive_ids bigint[] not null default '{}'::bigint[],
    add column if not exists affected_hives_snapshot jsonb not null default '[]'::jsonb;

alter table public.beekeep_workspace_action_log
    add constraint beekeep_workspace_action_log_structured_version_check
        check (structured_version in (0, 1)),
    add constraint beekeep_workspace_action_log_changes_array_check
        check (pg_catalog.jsonb_typeof(changes) = 'array'),
    add constraint beekeep_workspace_action_log_affected_hive_count_check
        check (affected_hive_count is null or affected_hive_count >= 0),
    add constraint beekeep_workspace_action_log_affected_hive_ids_array_check
        check (pg_catalog.cardinality(affected_hive_ids) >= 0),
    add constraint beekeep_workspace_action_log_affected_hives_snapshot_array_check
        check (pg_catalog.jsonb_typeof(affected_hives_snapshot) = 'array');

comment on column public.beekeep_workspace_action_log.structured_version is
    '0 = legacy description-only row; 1 = structured field-diff row.';
comment on column public.beekeep_workspace_action_log.apiary_id is
    'Historical target/location identifier only; deliberately has no business-record foreign key.';
comment on column public.beekeep_workspace_action_log.apiary_name_snapshot is
    'Apiary name captured when the action occurred, independent of later renames or deletion.';
comment on column public.beekeep_workspace_action_log.hive_id is
    'Historical target hive identifier only; deliberately has no business-record foreign key.';
comment on column public.beekeep_workspace_action_log.hive_name_snapshot is
    'Hive name/number captured when the action occurred, independent of later renames or deletion.';
comment on column public.beekeep_workspace_action_log.changes is
    'Allowlisted JSON array of {field, old_value, new_value}; excludes GPS, NFC UIDs, credentials, and secret fields.';
comment on column public.beekeep_workspace_action_log.affected_hive_ids is
    'Hive identifiers included in one Apiary-wide batch action; no foreign keys.';
comment on column public.beekeep_workspace_action_log.affected_hives_snapshot is
    'Action-time hive ID/name snapshots for expandable Apiary-wide batch entries.';

-- Resolve names from the workspace snapshot. The fallback is stored in the
-- originating document and remains useful when an old record was already removed.
create or replace function public.beekeep_workspace_action_log_resolve_apiary_name(
    target_workspace_id uuid,
    target_apiary_id bigint,
    fallback_name text default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $function$
declare
    resolved_name text;
begin
    if target_apiary_id is not null then
        select nullif(pg_catalog.btrim(d.payload::jsonb ->> 'name'), '')
          into resolved_name
          from public.beekeep_workspace_documents d
         where d.workspace_id = target_workspace_id
           and d.entity_type = 'apiary'
           and d.entity_id = target_apiary_id
         limit 1;
    end if;

    return coalesce(
        resolved_name,
        nullif(pg_catalog.btrim(fallback_name), ''),
        target_apiary_id::text
    );
end;
$function$;

create or replace function public.beekeep_workspace_action_log_resolve_hive_name(
    target_workspace_id uuid,
    target_hive_id bigint,
    fallback_name text default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $function$
declare
    resolved_name text;
begin
    if target_hive_id is not null then
        select nullif(pg_catalog.btrim(d.payload::jsonb ->> 'number'), '')
          into resolved_name
          from public.beekeep_workspace_documents d
         where d.workspace_id = target_workspace_id
           and d.entity_type = 'hive'
           and d.entity_id = target_hive_id
         limit 1;
    end if;

    return coalesce(
        resolved_name,
        nullif(pg_catalog.btrim(fallback_name), ''),
        target_hive_id::text
    );
end;
$function$;

-- Single allowlist for all structured diffs. Deliberately excludes precise
-- coordinates, NFC tag UIDs, tokens, email addresses, device IDs, and internal metadata.
create or replace function public.beekeep_workspace_action_log_build_changes(
    target_workspace_id uuid,
    target_entity_type text,
    previous_payload jsonb,
    current_payload jsonb,
    target_is_deleted boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
    field_keys text[];
    field_key text;
    old_value jsonb;
    new_value jsonb;
    old_apiary_id bigint;
    new_apiary_id bigint;
    old_apiary_name text;
    new_apiary_name text;
    result_changes jsonb := '[]'::jsonb;
begin
    field_keys := case target_entity_type
        when 'apiary' then array['name', 'notes', 'forage_notes', 'water_notes']
        when 'hive' then array[
            'number', 'status', 'queen_status', 'queen_mark_color',
            'queen_origin', 'queen_age_months', 'queen_temperament',
            'strength', 'mite_percent', 'bee_count_frames'
        ]
        when 'inspection' then array[
            'strength', 'queen_status', 'mite_count', 'sample_size',
            'eggs', 'open_brood', 'capped_brood', 'honey_stores', 'pollen',
            'empty_drawn_comb', 'emergency_cells', 'supercedure_cells',
            'swarm_cells', 'disease_flags', 'bee_count_frames', 'notes'
        ]
        when 'feeding' then array['feed_type', 'ratio', 'amount', 'unit', 'notes']
        when 'treatment' then array[
            'treatment_type', 'product', 'inserted_at', 'removal_at',
            'withdrawal_until', 'notes'
        ]
        when 'harvest' then array[
            'supers_pulled', 'wet_honey_weight', 'dry_honey_weight',
            'weight_unit', 'wax_weight', 'propolis_weight', 'notes'
        ]
        else array[]::text[]
    end;

    foreach field_key in array field_keys loop
        old_value := coalesce(previous_payload, '{}'::jsonb) -> field_key;
        new_value := case
            when target_is_deleted then null
            else coalesce(current_payload, '{}'::jsonb) -> field_key
        end;

        -- A first inspection has no historical baseline. Suppress form defaults
        -- so the log records observations, not untouched zero/blank controls.
        if target_entity_type = 'inspection'
           and coalesce(previous_payload, '{}'::jsonb) = '{}'::jsonb then
            if field_key = 'queen_status'
               and pg_catalog.lower(coalesce(new_value #>> '{}', 'laying')) = 'laying' then
                continue;
            elsif field_key = 'mite_count'
               and coalesce(nullif(new_value #>> '{}', '')::numeric, 0) = 0 then
                continue;
            elsif field_key = 'sample_size'
               and coalesce(nullif(current_payload ->> 'mite_count', '')::numeric, 0) = 0 then
                continue;
            elsif field_key in (
                'strength', 'eggs', 'open_brood', 'capped_brood', 'honey_stores',
                'pollen', 'empty_drawn_comb', 'emergency_cells', 'supercedure_cells',
                'swarm_cells', 'bee_count_frames'
            ) and coalesce(nullif(new_value #>> '{}', '')::numeric, 0) = 0 then
                continue;
            elsif field_key = 'disease_flags'
               and (new_value is null or new_value = '[]'::jsonb or new_value = '""'::jsonb) then
                continue;
            elsif field_key = 'notes'
               and coalesce(pg_catalog.btrim(new_value #>> '{}'), '') = '' then
                continue;
            end if;
        end if;

        -- Empty strings on newly-created records are untouched form defaults.
        if coalesce(previous_payload, '{}'::jsonb) = '{}'::jsonb
           and old_value is null
           and pg_catalog.jsonb_typeof(new_value) = 'string'
           and pg_catalog.btrim(new_value #>> '{}') = '' then
            continue;
        end if;

        -- Keep individual long text fields bounded in the audit table while
        -- preserving enough content for the UI's collapsed/expanded presentation.
        if pg_catalog.jsonb_typeof(old_value) = 'string'
           and pg_catalog.length(old_value #>> '{}') > 1000 then
            old_value := pg_catalog.to_jsonb(pg_catalog.left(old_value #>> '{}', 1000) || '…');
        end if;
        if pg_catalog.jsonb_typeof(new_value) = 'string'
           and pg_catalog.length(new_value #>> '{}') > 1000 then
            new_value := pg_catalog.to_jsonb(pg_catalog.left(new_value #>> '{}', 1000) || '…');
        end if;

        if old_value is distinct from new_value then
            result_changes := result_changes || pg_catalog.jsonb_build_array(
                pg_catalog.jsonb_build_object(
                    'field', field_key,
                    'old_value', old_value,
                    'new_value', new_value
                )
            );
        end if;
    end loop;

    -- A hive movement is presented as an Apiary-name transition, not an opaque ID.
    -- Do not add a location diff when a hive is first created.
    if target_entity_type = 'hive'
       and coalesce(previous_payload, '{}'::jsonb) ? 'apiary_id'
       and nullif(previous_payload ->> 'apiary_id', '')::bigint
           is distinct from nullif(current_payload ->> 'apiary_id', '')::bigint then
        old_apiary_id := nullif(previous_payload ->> 'apiary_id', '')::bigint;
        new_apiary_id := nullif(current_payload ->> 'apiary_id', '')::bigint;

        old_apiary_name := public.beekeep_workspace_action_log_resolve_apiary_name(
            target_workspace_id,
            old_apiary_id,
            previous_payload ->> 'apiary'
        );
        new_apiary_name := public.beekeep_workspace_action_log_resolve_apiary_name(
            target_workspace_id,
            new_apiary_id,
            current_payload ->> 'apiary'
        );

        result_changes := result_changes || pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object(
                'field', 'apiary',
                'old_value', old_apiary_name,
                'new_value', new_apiary_name
            )
        );
    end if;

    return result_changes;
end;
$function$;

revoke all on function public.beekeep_workspace_action_log_resolve_apiary_name(uuid, bigint, text)
    from public, anon, authenticated;
revoke all on function public.beekeep_workspace_action_log_resolve_hive_name(uuid, bigint, text)
    from public, anon, authenticated;
revoke all on function public.beekeep_workspace_action_log_build_changes(uuid, text, jsonb, jsonb, boolean)
    from public, anon, authenticated;

-- New inserts: normal entities and one-off Feed/Treatment/Harvest records.
create or replace function public.beekeep_workspace_action_log_after_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
    item record;
    item_payload jsonb;
    item_changes jsonb;
    item_action_type text;
    item_description text;
    item_apiary_id bigint;
    item_hive_id bigint;
    item_apiary_name text;
    item_hive_name text;
    item_fallback_apiary_name text;
    item_previous_payload jsonb;
begin
    for item in
        select
            n.workspace_id,
            n.entity_type,
            n.entity_id,
            n.payload,
            n.deleted,
            n.updated_at,
            n.updated_by,
            n.client_action_id,
            n.action_at,
            coalesce(nullif(pg_catalog.btrim(p.username), ''), 'Team member') as username
        from new_rows n
        left join public.beekeep_profiles p
          on p.user_id = coalesce(n.updated_by, (select auth.uid()))
        where n.entity_type in ('apiary', 'hive', 'inspection')
           or (
               n.entity_type in ('feeding', 'treatment', 'harvest')
               and nullif(n.payload::jsonb ->> 'batch_id', '') is null
           )
    loop
        item_payload := item.payload::jsonb;
        item_apiary_id := null;
        item_hive_id := null;
        item_apiary_name := null;
        item_hive_name := null;
        item_fallback_apiary_name := null;

        if item.entity_type = 'apiary' then
            item_apiary_id := item.entity_id;
            item_apiary_name := coalesce(
                nullif(pg_catalog.btrim(item_payload ->> 'name'), ''),
                item.entity_id::text
            );
        else
            if item.entity_type = 'hive' then
                item_hive_id := item.entity_id;
            else
                item_hive_id := nullif(item_payload ->> 'hive_id', '')::bigint;
            end if;

            item_apiary_id := nullif(item_payload ->> 'apiary_id', '')::bigint;
            item_fallback_apiary_name := item_payload ->> 'apiary';

            if item_hive_id is not null then
                item_hive_name := public.beekeep_workspace_action_log_resolve_hive_name(
                    item.workspace_id,
                    item_hive_id,
                    item_payload ->> 'number'
                );

                if item_apiary_id is null then
                    select nullif(d.payload::jsonb ->> 'apiary_id', '')::bigint
                      into item_apiary_id
                      from public.beekeep_workspace_documents d
                     where d.workspace_id = item.workspace_id
                       and d.entity_type = 'hive'
                       and d.entity_id = item_hive_id
                     limit 1;
                end if;
            end if;

            item_apiary_name := public.beekeep_workspace_action_log_resolve_apiary_name(
                item.workspace_id,
                item_apiary_id,
                item_fallback_apiary_name
            );
        end if;

        if item.entity_type in ('apiary', 'hive') and item.deleted then
            item_changes := public.beekeep_workspace_action_log_build_changes(
                item.workspace_id, item.entity_type, item_payload, '{}'::jsonb, true
            );
        elsif item.entity_type = 'inspection' then
            item_previous_payload := '{}'::jsonb;
            select d.payload::jsonb
              into item_previous_payload
              from public.beekeep_workspace_documents d
             where d.workspace_id = item.workspace_id
               and d.entity_type = 'inspection'
               and d.entity_id <> item.entity_id
               and not d.deleted
               and nullif(d.payload::jsonb ->> 'hive_id', '')::bigint =
                   nullif(item_payload ->> 'hive_id', '')::bigint
             order by d.updated_at desc, d.entity_id desc
             limit 1;
            item_changes := public.beekeep_workspace_action_log_build_changes(
                item.workspace_id,
                item.entity_type,
                coalesce(item_previous_payload, '{}'::jsonb),
                item_payload,
                false
            );
        else
            item_changes := public.beekeep_workspace_action_log_build_changes(
                item.workspace_id, item.entity_type, '{}'::jsonb, item_payload, false
            );
        end if;

        item_action_type := case
            when item.entity_type = 'apiary' and item.deleted then 'apiary_deleted'
            when item.entity_type = 'apiary' then 'apiary_added'
            when item.entity_type = 'hive' and item.deleted then 'hive_deleted'
            when item.entity_type = 'hive' then 'hive_added'
            when item.entity_type = 'inspection' then 'inspection_created'
            when item.entity_type = 'feeding' then 'feeding_added'
            when item.entity_type = 'treatment' then 'treatment_added'
            else 'harvest_added'
        end;

        if item.entity_type = 'inspection' then
            item_description := public.beekeep_inspection_action_log_description(
                item.workspace_id, item.entity_id, '{}'::jsonb, item_payload, true
            );
        else
            item_description := public.beekeep_workspace_action_log_description(
                item.workspace_id,
                item.entity_type,
                item.entity_id,
                item_payload,
                case
                    when item.entity_type in ('apiary', 'hive') and item.deleted then 'Deleted'
                    when item.entity_type in ('apiary', 'hive') then 'Added'
                    else 'Added'
                end
            );
        end if;

        insert into public.beekeep_workspace_action_log (
            workspace_id, client_action_id, user_id, username,
            action_type, target_type, target_id, description, action_at,
            structured_version, apiary_id, apiary_name_snapshot,
            hive_id, hive_name_snapshot, changes
        )
        values (
            item.workspace_id,
            coalesce(item.client_action_id, pg_catalog.gen_random_uuid()),
            coalesce(item.updated_by, (select auth.uid())),
            item.username,
            item_action_type,
            item.entity_type,
            item.entity_id::text,
            item_description,
            pg_catalog.to_timestamp(
                coalesce(nullif(item.action_at, 0), item.updated_at)::double precision / 1000.0
            ),
            1,
            item_apiary_id,
            item_apiary_name,
            item_hive_id,
            item_hive_name,
            item_changes
        )
        on conflict (workspace_id, client_action_id) do nothing;
    end loop;

    -- Each mass Apply-to-Apiary batch remains one log row. Store the full
    -- action-time affected-hive list and representative allowlisted batch values.
    with action_rows as (
        select
            n.workspace_id,
            n.entity_type,
            (n.payload::jsonb ->> 'batch_id')::uuid as batch_id,
            nullif(n.payload::jsonb ->> 'apiary_id', '')::bigint as apiary_id,
            nullif(n.payload::jsonb ->> 'hive_id', '')::bigint as hive_id,
            n.payload::jsonb as action_payload,
            coalesce(
                nullif(n.payload::jsonb ->> 'occurred_at', '')::bigint,
                nullif(n.payload::jsonb ->> 'created_at', '')::bigint,
                n.updated_at
            ) as action_at_ms,
            coalesce(n.updated_by, (select auth.uid())) as actor_id
        from new_rows n
        where n.entity_type in ('feeding', 'treatment', 'harvest')
          and nullif(n.payload::jsonb ->> 'batch_id', '') ~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ),
    grouped_batches as (
        select
            workspace_id,
            entity_type,
            batch_id,
            pg_catalog.max(apiary_id) as apiary_id,
            pg_catalog.count(distinct hive_id)::integer as hive_count,
            pg_catalog.max(action_at_ms) as action_at_ms,
            (pg_catalog.array_agg(actor_id))[1] as actor_id,
            (pg_catalog.array_agg(action_payload order by hive_id))[1] as action_payload,
            coalesce(
                pg_catalog.array_agg(distinct hive_id order by hive_id)
                    filter (where hive_id is not null),
                '{}'::bigint[]
            ) as affected_hive_ids
        from action_rows
        group by workspace_id, entity_type, batch_id
    )
    insert into public.beekeep_workspace_action_log (
        workspace_id, client_action_id, user_id, username,
        action_type, target_type, target_id, description, action_at,
        structured_version, apiary_id, apiary_name_snapshot,
        changes, affected_hive_count, affected_hive_ids, affected_hives_snapshot
    )
    select
        b.workspace_id,
        b.batch_id,
        b.actor_id,
        coalesce(nullif(pg_catalog.btrim(p.username), ''), 'Team member'),
        case b.entity_type
            when 'feeding' then 'mass_feed'
            when 'treatment' then 'mass_treatment'
            else 'mass_harvest'
        end,
        'batch',
        b.batch_id::text,
        pg_catalog.format(
            'Mass %s applied to Apiary %s (%s hives)',
            case b.entity_type
                when 'feeding' then 'feeding'
                when 'treatment' then 'treatment'
                else 'harvest'
            end,
            public.beekeep_workspace_action_log_resolve_apiary_name(
                b.workspace_id, b.apiary_id, nullif(a.payload::jsonb ->> 'name', '')
            ),
            b.hive_count
        ),
        pg_catalog.to_timestamp(b.action_at_ms::double precision / 1000.0),
        1,
        b.apiary_id,
        public.beekeep_workspace_action_log_resolve_apiary_name(
            b.workspace_id, b.apiary_id, nullif(a.payload::jsonb ->> 'name', '')
        ),
        public.beekeep_workspace_action_log_build_changes(
            b.workspace_id, b.entity_type, '{}'::jsonb, b.action_payload, false
        ),
        b.hive_count,
        b.affected_hive_ids,
        coalesce(hive_snapshots.snapshots, '[]'::jsonb)
    from grouped_batches b
    left join public.beekeep_profiles p on p.user_id = b.actor_id
    left join public.beekeep_workspace_documents a
      on a.workspace_id = b.workspace_id
     and a.entity_type = 'apiary'
     and a.entity_id = b.apiary_id
    left join lateral (
        select coalesce(
            pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'hive_id', ids.hive_id,
                    'name', public.beekeep_workspace_action_log_resolve_hive_name(
                        b.workspace_id,
                        ids.hive_id,
                        nullif(h.payload::jsonb ->> 'number', '')
                    )
                )
                order by ids.hive_id
            ),
            '[]'::jsonb
        ) as snapshots
        from pg_catalog.unnest(b.affected_hive_ids) as ids(hive_id)
        left join public.beekeep_workspace_documents h
          on h.workspace_id = b.workspace_id
         and h.entity_type = 'hive'
         and h.entity_id = ids.hive_id
    ) hive_snapshots on true
    where b.hive_count > 0
    on conflict (workspace_id, client_action_id) do nothing;

    return null;
end;
$function$;

revoke all on function public.beekeep_workspace_action_log_after_insert()
    from public, anon, authenticated;

drop trigger if exists beekeep_workspace_action_log_after_insert
    on public.beekeep_workspace_documents;
create trigger beekeep_workspace_action_log_after_insert
after insert on public.beekeep_workspace_documents
referencing new table as new_rows
for each statement
execute function public.beekeep_workspace_action_log_after_insert();

-- Updates compare only meaningful, allowlisted business fields. Metadata-only
-- writes, unchanged saves, and timestamp churn cannot generate audit rows.
create or replace function public.beekeep_workspace_action_log_after_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
    item record;
    old_payload jsonb;
    current_payload jsonb;
    effective_payload jsonb;
    item_changes jsonb;
    item_action_type text;
    item_description text;
    item_apiary_id bigint;
    item_hive_id bigint;
    item_apiary_name text;
    item_hive_name text;
    item_fallback_apiary_name text;
    item_is_deleted boolean;
begin
    for item in
        select
            n.workspace_id,
            n.entity_type,
            n.entity_id,
            n.payload,
            n.deleted,
            n.updated_at,
            n.updated_by,
            n.client_action_id,
            n.action_at,
            o.payload as old_payload,
            o.deleted as old_deleted,
            coalesce(nullif(pg_catalog.btrim(p.username), ''), 'Team member') as username
        from new_rows n
        join old_rows o
          on o.workspace_id = n.workspace_id
         and o.entity_type = n.entity_type
         and o.entity_id = n.entity_id
        left join public.beekeep_profiles p
          on p.user_id = coalesce(n.updated_by, (select auth.uid()))
        where n.entity_type in ('apiary', 'hive', 'inspection')
           or (
               n.entity_type in ('feeding', 'treatment', 'harvest')
               and nullif(n.payload::jsonb ->> 'batch_id', '') is null
           )
    loop
        old_payload := item.old_payload::jsonb;
        current_payload := item.payload::jsonb;
        item_is_deleted := item.deleted and not item.old_deleted;

        item_changes := public.beekeep_workspace_action_log_build_changes(
            item.workspace_id,
            item.entity_type,
            old_payload,
            current_payload,
            item_is_deleted
        );

        -- The allowlisted diff is the no-op test. Ignore updated_at, action_at,
        -- client_action_id, coordinates, NFC identifiers, and other metadata.
        if pg_catalog.jsonb_array_length(item_changes) = 0 then
            continue;
        end if;

        effective_payload := case
            when item_is_deleted then old_payload
            else current_payload
        end;

        item_apiary_id := null;
        item_hive_id := null;
        item_apiary_name := null;
        item_hive_name := null;
        item_fallback_apiary_name := effective_payload ->> 'apiary';

        if item.entity_type = 'apiary' then
            item_apiary_id := item.entity_id;
            item_apiary_name := coalesce(
                nullif(pg_catalog.btrim(effective_payload ->> 'name'), ''),
                item.entity_id::text
            );
        else
            if item.entity_type = 'hive' then
                item_hive_id := item.entity_id;
            else
                item_hive_id := nullif(effective_payload ->> 'hive_id', '')::bigint;
            end if;

            item_apiary_id := nullif(effective_payload ->> 'apiary_id', '')::bigint;

            if item_hive_id is not null then
                item_hive_name := public.beekeep_workspace_action_log_resolve_hive_name(
                    item.workspace_id,
                    item_hive_id,
                    effective_payload ->> 'number'
                );

                if item_apiary_id is null then
                    select nullif(d.payload::jsonb ->> 'apiary_id', '')::bigint
                      into item_apiary_id
                      from public.beekeep_workspace_documents d
                     where d.workspace_id = item.workspace_id
                       and d.entity_type = 'hive'
                       and d.entity_id = item_hive_id
                     limit 1;
                end if;
            end if;

            item_apiary_name := public.beekeep_workspace_action_log_resolve_apiary_name(
                item.workspace_id,
                item_apiary_id,
                item_fallback_apiary_name
            );
        end if;

        item_action_type := case
            when item.entity_type = 'apiary' and item_is_deleted then 'apiary_deleted'
            when item.entity_type = 'apiary' then 'apiary_edited'
            when item.entity_type = 'hive' and item_is_deleted then 'hive_deleted'
            when item.entity_type = 'hive' then 'hive_edited'
            when item.entity_type = 'inspection' then 'inspection_edited'
            when item.entity_type = 'feeding' then 'feeding_edited'
            when item.entity_type = 'treatment' then 'treatment_edited'
            else 'harvest_edited'
        end;

        if item.entity_type = 'inspection' then
            item_description := public.beekeep_inspection_action_log_description(
                item.workspace_id,
                item.entity_id,
                old_payload,
                current_payload,
                false
            );
        else
            item_description := public.beekeep_workspace_action_log_description(
                item.workspace_id,
                item.entity_type,
                item.entity_id,
                effective_payload,
                case when item_is_deleted then 'Deleted' else 'Edited' end
            );
        end if;

        insert into public.beekeep_workspace_action_log (
            workspace_id, client_action_id, user_id, username,
            action_type, target_type, target_id, description, action_at,
            structured_version, apiary_id, apiary_name_snapshot,
            hive_id, hive_name_snapshot, changes
        )
        values (
            item.workspace_id,
            coalesce(item.client_action_id, pg_catalog.gen_random_uuid()),
            coalesce(item.updated_by, (select auth.uid())),
            item.username,
            item_action_type,
            item.entity_type,
            item.entity_id::text,
            item_description,
            pg_catalog.to_timestamp(
                coalesce(nullif(item.action_at, 0), item.updated_at)::double precision / 1000.0
            ),
            1,
            item_apiary_id,
            item_apiary_name,
            item_hive_id,
            item_hive_name,
            item_changes
        )
        on conflict (workspace_id, client_action_id) do nothing;
    end loop;

    return null;
end;
$function$;

revoke all on function public.beekeep_workspace_action_log_after_update()
    from public, anon, authenticated;

drop trigger if exists beekeep_workspace_action_log_after_update
    on public.beekeep_workspace_documents;
create trigger beekeep_workspace_action_log_after_update
after update on public.beekeep_workspace_documents
referencing old table as old_rows new table as new_rows
for each statement
execute function public.beekeep_workspace_action_log_after_update();

commit;
